<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {useLearningStore} from '../stores/learning';import TradingChart from '../components/chart/TradingChart.vue';import {api} from '../services/api';import type {Candle,Dataset,PageResult} from '../types';const route=useRoute(),store=useLearningStore(),timeframe=ref<'1H'|'4H'|'1D'>('1H'),start=ref('2024-01-01'),end=ref(new Date().toISOString().slice(0,10)),name=ref(''),message=ref(''),saving=ref(false),preview=ref<{dataset:Dataset;candles:Candle[]}|null>(null),examples=ref<unknown[]>([]);async function add(){saving.value=true;message.value='Đang tải lịch sử và tạo ví dụ chuẩn hóa…';try{await store.add({timeframe:timeframe.value,start:start.value,end:end.value,name:name.value||undefined});message.value='Dataset đã lưu vào SQLite.'}catch(e){message.value=e instanceof Error?e.message:'Không thể tạo dataset'}finally{saving.value=false}}async function view(d:Dataset){preview.value=await store.view(d.id);examples.value=[]}async function showExamples(d:Dataset){const r=await api<PageResult<unknown>>(`/api/learning/datasets/${d.id}/examples?page=1&limit=10`);preview.value=null;examples.value=r.items}async function remove(d:Dataset){if(!confirm(`Xóa dataset “${d.name}”? Lịch sử dự báo sẽ được giữ nguyên.`))return;await store.remove(d.id);if(preview.value?.dataset.id===d.id)preview.value=null}onMounted(async()=>{await store.load(1);const id=route.query.dataset;if(typeof id==='string')preview.value=await api<{dataset:Dataset;candles:Candle[]}>(`/api/learning/datasets/${id}/candles`)});</script>
<template><section class="view"><div class="page-heading"><div><div class="eyebrow">PATTERN ENGINE</div><h1>Chart Learning</h1><p>Học cấu trúc nến chuẩn hóa, tách riêng theo timeframe. Nến trùng được chia sẻ trong market_candles.</p></div><button class="icon-button" @click="store.load()">⟳</button></div><div class="panel learning-form"><div class="panel-title"><span>THÊM DỮ LIỆU HỌC</span><span class="muted">Binance · BTC/USDT</span></div><div class="form-grid"><label>Khung thời gian<select v-model="timeframe"><option>1H</option><option>4H</option><option>1D</option></select></label><label>Từ ngày<input v-model="start" type="date"></label><label>Đến ngày<input v-model="end" type="date"></label><label>Tên dataset<input v-model="name" placeholder="Tùy chọn"></label><button class="predict-button" :disabled="saving" @click="add">{{saving?'Đang học…':'＋ Thêm dữ liệu học'}}</button></div><div class="message">{{message||store.error}}</div></div><div class="panel"><div class="panel-title"><span>DATASET ĐÃ HỌC</span><span class="muted">{{store.datasets.length}} trong trang · {{store.pages}} trang</span></div><div class="dataset-list"><div v-if="store.loading" class="empty-row">Đang tải…</div><div v-else-if="!store.datasets.length" class="empty-row">Chưa có dataset.</div><div v-for="d in store.datasets" :key="d.id" class="dataset-row"><span><b>{{d.name}}</b><br><small>{{d.symbol}} · {{d.timeframe}} · {{new Date(d.start_time*1000).toLocaleDateString()}} – {{new Date(d.end_time*1000).toLocaleDateString()}}</small><br><small>{{d.candle_count}} nến · {{d.example_count}} ví dụ · {{new Date(d.created_at).toLocaleString()}}</small></span><span class="dataset-actions"><button @click="view(d)">Biểu đồ</button><button @click="showExamples(d)">Ví dụ</button><button @click="remove(d)">Xóa</button></span></div></div><div class="pagination"><button :disabled="store.page<=1" @click="store.load(store.page-1)">‹ Trước</button><span>{{store.page}} / {{store.pages||1}}</span><button :disabled="store.page>=store.pages" @click="store.load(store.page+1)">Sau ›</button></div></div><div v-if="preview" class="panel"><div class="panel-title"><span>{{preview.dataset.name}} · BIỂU ĐỒ</span><button class="icon-button" @click="preview=null">×</button></div><TradingChart :candles="preview.candles" :forecast="null" :timeframe="preview.dataset.timeframe" :volume-visible="true"/></div><div v-if="examples.length" class="panel"><div class="panel-title"><span>VÍ DỤ PATTERN · 10 GẦN NHẤT</span><button class="icon-button" @click="examples=[]">×</button></div><pre class="example-json">{{JSON.stringify(examples,null,2)}}</pre></div></section></template>
